onMessageSendError(aCurrentMessage, aMessageHeader, aStatus) {
  this._reject(new Error(aStatus));
}

onStopSending(status, msg, totalTried, successful) {
  if (status != Cr.NS_OK) {
    this._reject(new Error(status));
    return;
  }

  this._resolve({
    status,
    msg,
    totalTried,
    successful,
  });
}
